'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var Clip = require( '@stdlib/plot/vega/mark/clip' );


// MAIN //

/**
* Tests whether an input value is an clip instance.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an clip instance
*
* @example
* var Clip = require( '@stdlib/plot/vega/mark/clip' );
*
* var v = new Clip();
* var bool = isClip( v );
* // returns true
*
* bool = isClip( {} );
* // returns false
*
* bool = isClip( 'foo' );
* // returns false
*/
function isClip( value ) {
	return (
		value instanceof Clip ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			isString( value.type ) &&
			isBoolean( value.resize ) &&
			isString( value.contains )
		)
	);
}


// EXPORTS //

module.exports = isClip;
